def fingerprint(value):
    return hashlib.sha256(value.encode('utf-8')).hexdigest()[:12]


class ReceiptDispatcher:
    def __init__(self, queue):
        self.queue = queue

    def dispatch(self, order_id, email):
        fp = fingerprint(email)
        logger.info('receipt dispatch queue=%s order=%s email_fp=%s', self.queue, order_id, fp)
        return {'order_id': order_id, 'email_fp': fp}


