class InvoiceRetentionJob:
    def __init__(self, session, keep_days):
        self.session = session
        self.keep_days = keep_days

    def receipt(self, removed, contact_email):
        return {'removed': removed, 'kept_days': self.keep_days, 'contact': contact_email}

    def run(self):
        cutoff = datetime.utcnow() - timedelta(days=self.keep_days)
        stale = self.session.query(Invoice).filter(Invoice.issued_at < cutoff)
        first = stale.first()
