from flask import Blueprint, g, jsonify

from app.auth import login_required
from app.masking import mask_secret
from app.models import ApiKey

account_bp = Blueprint('account_keys', __name__)


class KeyListPresenter:
    def __init__(self, include_revoked):
        self.include_revoked = include_revoked

    def row(self, key, masked):
        return {
            'id': key.public_id,
            'label': key.label,
            'created_at': key.created_at.isoformat(),
            'key': masked,
            'revoked': key.revoked_at is not None,
        }

    def render(self, keys):
        rows = []
        for key in keys:
            if key.revoked_at is not None and not self.include_revoked:
                continue
            rows.append(self.row(key=key, masked=mask_secret(key.raw_hint)))
        return rows


@account_bp.get('/account/api-keys')
@login_required
def list_keys():
    presenter = KeyListPresenter(include_revoked=False)
    return jsonify({'keys': presenter.render(ApiKey.for_user(g.current_user.id))})
